<?php
require_once __DIR__.'/../api-auth.php';require_once __DIR__.'/../../../includes/student-communication-api.php';
$student=requireApiStudent($pdo);$userId=(int)$student['user_id'];$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');
try{
    if($method==='GET'){$q=$pdo->prepare('SELECT identifiant_public uuid,plateforme platform,nom_appareil device_name,version_application app_version,actif active,derniere_activite_le last_seen_at FROM mobile_notification_devices WHERE utilisateur_id=? ORDER BY derniere_activite_le DESC');$q->execute([$userId]);$items=$q->fetchAll(PDO::FETCH_ASSOC);foreach($items as &$i)$i['active']=(bool)$i['active'];unset($i);apiResponse(true,'',['items'=>$items]);}
    if($method==='POST'){$input=apiInput();$token=trim((string)($input['token']??''));$platform=strtolower(trim((string)($input['platform']??'')));if(strlen($token)<20||strlen($token)>512||!in_array($platform,['android','ios','web'],true))apiResponse(false,'Appareil ou jeton push invalide.',[],422);$hash=hash('sha256',$token);$uuid=communicationUlid();$q=$pdo->prepare("INSERT INTO mobile_notification_devices(identifiant_public,utilisateur_id,plateforme,jeton,jeton_hash,nom_appareil,version_application,actif) VALUES(?,?,?,?,?,?,?,1) ON DUPLICATE KEY UPDATE identifiant_public=IF(utilisateur_id=VALUES(utilisateur_id),identifiant_public,VALUES(identifiant_public)),utilisateur_id=VALUES(utilisateur_id),plateforme=VALUES(plateforme),jeton=VALUES(jeton),nom_appareil=VALUES(nom_appareil),version_application=VALUES(version_application),actif=1,derniere_activite_le=UTC_TIMESTAMP(6)");$q->execute([$uuid,$userId,$platform,$token,$hash,mb_substr(trim((string)($input['device_name']??'')),0,150)?:null,mb_substr(trim((string)($input['app_version']??'')),0,50)?:null]);$q=$pdo->prepare('SELECT identifiant_public FROM mobile_notification_devices WHERE jeton_hash=? AND utilisateur_id=?');$q->execute([$hash,$userId]);apiResponse(true,'Appareil enregistre.',['uuid'=>$q->fetchColumn(),'platform'=>$platform],201);}
    header('Allow: GET, POST');apiResponse(false,'Methode HTTP non autorisee.',[],405);
}catch(Throwable $e){error_log('[API NOTIFICATION DEVICES] '.$e->getMessage());apiResponse(false,'Impossible de gerer les appareils.',[],500);}
